mapper.select:
select cls.PTL_ID ptlId, cls.ASSET_POSITION assetPosition, sdl.ITEM_VALUE assetType, cls.FINPROD_ID finprodId, fp.FINPROD_NAME finprodName, cls.VAL_DATE valDate from CREDIT_LINES_SEC_POSITION cls left join FIN_PRODUCT fp on fp.FINPROD_ID = cls.FINPROD_ID left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = fp.FINPROD_ID left join SYS_DATADICT_LIST sdl on sdl.ITEM_CODE = fpt.TYPE_8 and sdl.DICT_CODE = 'PINAN_ASSET_TYPE'
cls.PTL_ID = #{ptlId, jdbcType=VARCHAR}
and cls.FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
and cls.PTL_ID = #{ptlId, jdbcType=VARCHAR}
and cls.VAL_DATE = STR_TO_DATE(#{valDate, jdbcType=DATE}, '%Y-%m-%d')
and fpt.TYPE_8 = #{assetType, jdbcType=VARCHAR}
and cls.ASSET_POSITION = #{assetPosition, jdbcType=VARCHAR}

mapper.insert:
insert into CREDIT_LINES_SEC_POSITION (SEQNO,VAL_DATE,PTL_ID,SUB_CODE,FINPROD_ID,CREDIT_OCCURE_TYPE, TRADE_AMT,ASSET_POSITION,CREATE_USER,CREATE_DEPT,CREATE_TIME,UPDATE_USER,UPDATE_TIME) values(
#{item.seqno, jdbcType=VARCHAR} SEQNO, #{item.valDate, jdbcType=DATE} VAL_DATE, #{item.ptlId, jdbcType=VARCHAR} PTL_ID, #{item.subCode, jdbcType=VARCHAR} SUB_CODE, #{item.finprodId, jdbcType=VARCHAR} FINPROD_ID, #{item.creditOccureType, jdbcType=VARCHAR} CREDIT_OCCURE_TYPE, #{item.tradeAmt, jdbcType=VARCHAR} TRADE_AMT, #{item.assetPosition, jdbcType=VARCHAR} ASSET_POSITION, #{item.createUser, jdbcType=VARCHAR} CREATE_USER, #{item.createDept, jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime, jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser, jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime, jdbcType=TIMESTAMP} UPDATE_TIME
)
